import{_ as n,o as r,c as i,a3 as l}from"./chunks/framework.z_KJ15Ep.js";const o=JSON.parse('{"title":"Schüler suchen, filtern und gruppieren","description":"","frontmatter":{},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse.md","filePath":"schild3/suchen-gruppenprozesse.md"}'),a={name:"schild3/suchen-gruppenprozesse.md"};function s(u,e,h,t,c,d){return r(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="schuler-suchen-filtern-und-gruppieren" tabindex="-1">Schüler suchen, filtern und gruppieren <a class="header-anchor" href="#schuler-suchen-filtern-und-gruppieren" aria-label="Permalink to &quot;Schüler suchen, filtern und gruppieren&quot;">​</a></h1><p>Stellen Sie die gewünschte Schülergruppe zusammen, bevor Sie Reports ausgeben oder gemeinsame Änderungen starten. Der <a href="/schild3/suchen-gruppenprozesse/schuelercontainer-schueler.html">Schülercontainer</a> zeigt, welche Datensätze aktuell ausgewählt sind.</p><h2 id="einzelne-personen-oder-einfache-gruppen-finden" tabindex="-1">Einzelne Personen oder einfache Gruppen finden <a class="header-anchor" href="#einzelne-personen-oder-einfache-gruppen-finden" aria-label="Permalink to &quot;Einzelne Personen oder einfache Gruppen finden&quot;">​</a></h2><ul><li><a href="/schild3/suchen-gruppenprozesse/schuelersuche-schueler.html">Eine Schülerin oder einen Schüler suchen</a> für Name, Anschrift, Geburtsdatum oder Statistiknummer.</li><li><a href="/schild3/suchen-gruppenprozesse/schuelercontainer-schueler.html">Die Schülerauswahl im Container verwenden</a> für die Schnellfilter nach Status, Klasse, Kurs und Jahrgang.</li><li><a href="/schild3/schueler/menueband-auswahl.html">Das Menüband zur Schülerauswahl verwenden</a> zum Zurücksetzen der Auswahl und zum Aufrufen gespeicherter Filter.</li></ul><h2 id="mehrere-bedingungen-kombinieren" tabindex="-1">Mehrere Bedingungen kombinieren <a class="header-anchor" href="#mehrere-bedingungen-kombinieren" aria-label="Permalink to &quot;Mehrere Bedingungen kombinieren&quot;">​</a></h2><p>Beginnen Sie mit der Anleitung <a href="/schild3/suchen-gruppenprozesse/benutzung-des-schuelerfilters-tutorial.html">Schüler mit kombinierten Filterbedingungen auswählen</a>. Die <a href="/schild3/suchen-gruppenprozesse/schuelerfilter-auswahl.html">Referenz zum Schülerfilter</a> erläutert Verknüpfungen, Testen, Übernehmen und Speichern im Detail.</p><h2 id="eine-auswahl-wiederverwenden" tabindex="-1">Eine Auswahl wiederverwenden <a class="header-anchor" href="#eine-auswahl-wiederverwenden" aria-label="Permalink to &quot;Eine Auswahl wiederverwenden&quot;">​</a></h2><ul><li><a href="/schild3/schueler/individuelle-schuelergruppen-bearbeiten-und-nutzen-tutorial.html">Individuelle Schülergruppen anlegen und verwenden</a> für eine frei zusammengestellte Gruppe.</li><li><a href="/schild3/unterricht-kataloge/schuelergruppe-bearbeiten-schulbezogene-kataloge.html">Individuelle Schülergruppen im Katalog verwalten</a> zum Vorbereiten der Gruppennamen.</li><li><a href="/schild3/suchen-gruppenprozesse/sortierung-des-schuelercontainers-aendern-tutorial.html">Die Sortierung der Schülerauswahl ändern</a> für eine zur Aufgabe passende Reihenfolge.</li></ul><p>Gemeinsame Änderungen finden Sie bei <a href="/schild3/gruppenprozesse.html">Allgemeine Gruppenprozesse</a>, <a href="/schild3/faecher-kurse.html">Fächer und Kurse zuweisen</a> sowie <a href="/zeugnisse/vorbereitung.html">Zeugnisse vorbereiten</a>.</p>',9)])])}const g=n(a,[["render",s]]);export{o as __pageData,g as default};
